  'مكنسة برميلية فائقة القوة لشفط الأتربة والمياه والمواد الرطبة مع خزان معدني عملاق بسعة 21 لتر.',
  'مكنسة كهربائية للخدمة الشاقة والتنظيف المنزلي والورشي العميق بقوة شفط جبارة تبلغ 2200 وات. تأتي بتصميم برميلي متين مع خزان حديدي معزز ضد الصدأ بسعة 21 لتر تتيح لك شفط كميات هائلة من الأتربة وحتى المياه والمواد السائلة المنسكبة بكفاءة تامة. مزودة بخاصية طرد الهواء (البلاور) المتميزة لإزالة أوراق الشجر والأتربة الصعبة من الممرات والزوايا المظلمة.',
  'مكنسة كهربائية للخدمة الشاقة والتنظيف المنزلي والورشي العميق بقوة شفط جبارة تبلغ 2200 وات. تأتي بتصميم برميلي متين مع خزان حديدي معزز ضد الصدأ بسعة 21 لتر تتيح لك شفط كميات هائلة من الأتربة وحتى المياه والمواد السائلة المنسكبة بكفاءة تامة. مزودة بخاصية طرد الهواء (البلاور) المتميزة لإزالة أوراق الشجر والأتربة الصعبة من الممرات والزوايا المظلمة.',
  '{"القدرة بالوات": "2200 واط (محرك توربو جبار)", "سعة خزان الغبار/السوائل": "21 لتر (خزان حديدي صلب مجلفن)", "نوع الفلتر": "فلتر HEPA متعدد الطبقات يمنع خروج الأتربة", "وظيفة طرد الهواء (Blower)": "نعم، متوفرة بقوة دفع هواء ممتازة", "طول السلك": "8 أمتار لسهولة التحرك والتنظيف الواسع", "الملحقات المرفقة": "فرشاة السجاد والأرضيات، فوهة الشقوق الضيقة"}'::jsonb,
  5100.00, true, true,
  '["خزان برميلي معدني متين لا يصدأ وعملاق", "خاصية البلاور (طارد الهواء) لإزالة الأتربة", "فلتر HEPA صحي وقابل للغسل لضمان نقاء كامل"]'::jsonb
),
(
  'e390f1ee-7c54-4b01-90e6-e701748f0c26', 'd290f1ee-6c54-4b01-90e6-d701748f0857',
  'مكنسة لاسلكية ذكية خفيفة الوزن', 'smart-cordless-handheld-vacuum',
  'مكنسة لاسلكية عمودية ببطارية ليثيوم طويلة الأمد وقوة شفط توربينية فائقة لسهولة تنظيف الأثاث والسيارة.',
  'ودع فوضى الأسلاك ومشاكل التنقل. مكنسة لاسلكية فائقة الخفة بوزن 1.8 كجم فقط تتيح لك تنظيف الأرضيات، الأسقف، الأثاث، والستائر وداخل السيارة بحرية تامة بفضل الملحقات المتنوعة. تعمل بمحرك رقمي ذكي يغير قوة الشفط تلقائياً بناء على نوع السجاد أو السيراميك، وببطارية ليثيوم قابلة للاستبدال تمنحك حتى 45 دقيقة من العمل المستمر.',
  'ودع فوضى الأسلاك ومشاكل التنقل. مكنسة لاسلكية فائقة الخفة بوزن 1.8 كجم فقط تتيح لك تنظيف الأرضيات، الأسقف، الأثاث، والستائر وداخل السيارة بحرية تامة بفضل الملحقات المتنوعة. تعمل بمحرك رقمي ذكي يغير قوة الشفط تلقائياً بناء على نوع السجاد أو السيراميك، وببطارية ليثيوم قابلة للاستبدال تمنحك حتى 45 دقيقة من العمل المستمر.',
  '{"القدرة بالوات": "400 واط (محرك رقمي بروشليس)", "نوع المكنسة": "لاسلكية عمودية ومحمولة 2 في 1", "سعة البطارية": "تعمل حتى 45 دقيقة متواصلة بالشحن السريع", "وزن الجهاز صافي": "1.8 كجم (سهلة الحمل بيد واحدة)", "خزان الأتربة": "سعة 0.6 لتر بضغطة زر واحدة للتفريغ الصحي", "إضاءة فرشاة السجاد": "نعم، مجهزة بكشافات LED لكشف الغبار تحت الأثاث"}'::jsonb,
  8500.00, false, true,
  '["تصميم لاسلكي وخفيف للغاية يمنحك راحة وسرعة", "مستشعرات ذكية لتعديل قوة الشفط تلقائياً", "فراغات فرشاة مضادة لالتفاف خصل الشعر"]'::jsonb
),
(
  'e390f1ee-7c54-4b01-90e6-e701748f0c27', 'd290f1ee-6c54-4b01-90e6-d701748f0857',
  'مكنسة روبوت ذكية مع مسح رطب', 'smart-robotic-vacuum-mop',
  'مكنسة ذكية تقوم بالكنس والمسح التلقائي بالكامل بفضل مستشعرات رسم الخرائط للغرف والتحكم عن بعد بالموبايل.',
  'دع الروبوت يقوم بكامل أعمال نظافة الأرضيات بالنيابة عنك. مكنسة وممسحة روبوتية ذكية تكنس وتمسح السيراميك والباركيه تلقائياً وتتجنب السقوط من السلالم أو الاصطدام بالأثاث بفضل مستشعرات الليدار المتطورة لرسم خرائط الغرف بدقة متناهية. يمكنك جدولة وقت التنظيف اليومي عبر تطبيق الهاتف وتتبع مساره والتحكم به حتى وأنت خارج المنزل.',
  'دع الروبوت يقوم بكامل أعمال نظافة الأرضيات بالنيابة عنك. مكنسة وممسحة روبوتية ذكية تكنس وتمسح السيراميك والباركيه تلقائياً وتتجنب السقوط من السلالم أو الاصطدام بالأثاث بفضل مستشعرات الليدار المتطورة لرسم خرائط الغرف بدقة متناهية. يمكنك جدولة وقت التنظيف اليومي عبر تطبيق الهاتف وتتبع مساره والتحكم به حتى وأنت خارج المنزل.',
  '{"نوع التنظيف": "كنس ومسح (رطب وجاف بنظام تحكم ذكي بقطرات الماء)", "قوة الشفط القصوى": "3000 باسكال", "عمر البطارية": "تصل إلى 120 دقيقة (تقوم بالرجوع لقاعدة الشحن ذاتياً)", "نظام الملاحة": "مستشعرات ليدار متطورة ورسم خريطة تفاعلية", "سعة خزان الأتربة/المياه": "خزان غبار 400 مل / خزان مياه 250 مل", "الاتصال الذكي": "واي فاي للتحكم بالكامل عبر تطبيق الموبايل"}'::jsonb,
  14900.00, false, true,
  '["كنس ومسح ذكي متكامل بجهاز واحد", "توجيه ورسم خرائط الليزر الذكي لضمان تنظيف كل شبر", "شحن ذاتي والعودة التلقائية إلى منصة الشحن"]'::jsonb
),
(
  'e390f1ee-7c54-4b01-90e6-e701748f0c28', 'd290f1ee-6c54-4b01-90e6-d701748f0857',
  'مكنسة غسيل السجاد والكنب بقوة 1800 واط', 'carpet-and-upholstery-washer-vacuum-1800w',
  'مكنسة غسيل عميق متطورة تقوم بضخ الشامبو والماء الدافئ لغسل وتجفيف السجاد والمفروشات بلمح البصر.',
  'الحل الاحترافي لتنظيف وغسيل السجاد والكنب والمراتب في المنزل دون الحاجة لشركات تنظيف مكلفة. مكنسة غسيل عميق بقوة 1800 واط تعمل بنظام خزانين منفصلين (خزان للماء النظيف والشامبو وخزان للماء المتسخ المسحوب). تقوم بضخ محلول التنظيف داخل أنسجة السجاد مع فرك وتجفيف حراري سريع للغاية لتستعيد المفروشات رونقها ورائحتها الجميلة في دقائق.',
  'الحل الاحترافي لتنظيف وغسيل السجاد والكنب والمراتب في المنزل دون الحاجة لشركات تنظيف مكلفة. مكنسة غسيل عميق بقوة 1800 واط تعمل بنظام خزانين منفصلين (خزان للماء النظيف والشامبو وخزان للماء المتسخ المسحوب). تقوم بضخ محلول التنظيف داخل أنسجة السجاد مع فرك وتجفيف حراري سريع للغاية لتستعيد المفروشات رونقها ورائحتها الجميلة في دقائق.',
  '{"القدرة بالوات": "1800 واط", "سعة خزان المياه النظيفة": "3.5 لتر", "سعة خزان المياه المتسخة": "3 لتر", "نظام التنظيف": "ضخ شامبو + فرك آلي + شفط وتجفيف حراري", "طول خرطوم الغسيل": "2.5 متر مع فرش متعددة المقاسات"}'::jsonb,
  11200.00, false, false, -- غير متوفر لتجربة الشارة
  '["تنظيف عميق وإزالة أصعب البقع والروائح الكريهة", "نظام تجفيف حراري سريع يمنع الرطوبة والعفن", "مجموعة فراش متخصصة للكنب والستائر والزوايا"]'::jsonb
);

