INSERT INTO site_content (key, value, content_type) VALUES
('home_hero_badge', 'الوكيل الرسمي والمعتمد لأقوى الأجهزة المنزلية والكهربائية', 'text'),
('home_hero_title', 'شركة الصفوة للأجهزة المنزلية', 'text'),
('home_hero_tagline', 'قوة الأداء وعمر أطول لكل جهاز في منزلك', 'text'),
('home_hero_description', 'الخيار الأول والوكيل الأبرز لكل منزل وعائلة في مصر تبحث عن الأجهزة الموثوقة التي تتميز بالتحمل الفائق والذكاء التكنولوجي الحديث مع أطول فترات الضمان والصيانة المعتمدة.', 'text'),
